changeSet.sql:
create or alter procedure [integration].[MergeAssetHashes] ( @SynchedAssetTypeID int, @Section smallint, @RequestNumber int, @Hashes IntegrationAssetHashType READONLY ) as begin merge integration.AssetHash as T using @Hashes as S on (T.SynchedAssetTypeID = S.SynchedAssetTypeID and T.Section = S.Section and T.SourceID = S.SourceID) when matched then update set T.RequestNumber = S.RequestNumber,
T.[UpdateHash] = S.[Hash], T.[Action] = case when T.[Hash] = S.[Hash] then 'N' else 'U' end when not matched then insert (SynchedAssetTypeID, Section, RequestNumber, SourceID, [UpdateHash], [Action]) values (S.SynchedAssetTypeID, S.Section, S.RequestNumber, S.SourceID, S.[Hash], 'A');
select * from integration.AssetHash where SynchedAssetTypeID = @SynchedAssetTypeID and Section = @Section and RequestNumber = @RequestNumber and [Action] in ('A', 'U'); end
